<script setup>
import CustomerRecords from './CustomerRecords.vue';
import PricingPresets from './PricingPresets.vue';
import StockPriceOverrides from './StockPriceOverrides.vue';
import PricingCoverage from './PricingCoverage.vue';
import {stockPricingCoverage,addCoverageOverrides} from '../shared/stock-pricing.mjs';
import {ref,computed,watch} from 'vue';
import {printableQuote} from '../shared/quote-print.mjs';
import {quoteCosting,moneyToCents,validateQuoteDetails,validatePricing} from '../shared/quote.mjs';
import {WOOD_IDS,METAL_IDS} from '../shared/materials.mjs';
const woodRates=()=>Object.fromEntries(WOOD_IDS.map(id=>[id,'0.00']));
const props=defineProps({revision:{type:Object,required:true},busy:Boolean,jobName:{type:String,default:''},focusId:{type:String,default:''}}),emit=defineEmits(['save','export','print','status']);
const statusActor=ref(''),statusNote=ref('');
// Placed designs can add metal sheets and profile stock (priced per metre).
const metals=computed(()=>[...new Set(props.revision.manifest.batches.map(b=>b.material))].filter(id=>METAL_IDS.includes(id)));
const profileRows=computed(()=>props.revision.manifest.profiles??[]),profilePrices=ref({});
function setStatus(status){emit('status',{quoteId:saved.value.id,status,expectedEvent:saved.value.lifecycle?.events.length??0,actor:statusActor.value,note:statusNote.value});}
const details=ref({customer:'',reference:'',notes:''});
const stockRates=ref([]);
const includeEdging=ref(false),edgeMaterial=ref('0.00'),edgeLabour=ref('0.00'),edgeWaste=ref(0);
const currency=ref('EUR'),rates=ref({...woodRates(),handles:'0.00',labour:'0.00'}),minutes=ref(0),markup=ref(0),choice=ref('');
const pricing=()=>{if(typeof markup.value!=='number'||!Number.isFinite(markup.value)||markup.value<0||markup.value>100||Math.abs(markup.value*100-Math.round(markup.value*100))>1e-6)throw Error('Enter markup from 0 to 100 with up to two decimals');if(includeEdging.value&&(!Number.isFinite(edgeWaste.value)||edgeWaste.value<0||edgeWaste.value>100||Math.abs(edgeWaste.value*100-Math.round(edgeWaste.value*100))>1e-6))throw Error('Enter edging waste from 0 to 100 with up to two decimals');return {...(stockRates.value.length?{stockRates:stockRates.value.map(row=>({material:row.material,thicknessMm:row.thicknessMm,stockLengthMm:row.stockLengthMm,stockWidthMm:row.stockWidthMm,unitCents:moneyToCents(row.price)}))}:{}),...(includeEdging.value?{edging:{materialCentsPerMetre:moneyToCents(edgeMaterial.value),labourCentsPerMetre:moneyToCents(edgeLabour.value),wasteBps:Math.round(edgeWaste.value*100)}}:{}),currency:currency.value,sheetRates:Object.fromEntries([...WOOD_IDS,...metals.value].map(id=>[id,moneyToCents(rates.value[id]??'0.00')])),...(profileRows.value.length?{profileRates:Object.fromEntries(profileRows.value.map(g=>[g.key,moneyToCents(profilePrices.value[g.key]??'0.00')]))}:{}),handleUnitCents:moneyToCents(rates.value.handles),labourHourlyCents:moneyToCents(rates.value.labour),labourMinutesPerPanel:minutes.value,markupBps:Math.round(markup.value*100)};};
const presetPricing=computed(()=>{try{return validatePricing(pricing());}catch{return null;}});
function applyPricingPreset(input){
 const p=validatePricing(input),money=v=>(v/100).toFixed(2);
 stockRates.value=(p.stockRates??[]).map(row=>({...row,price:money(row.unitCents)}));
 currency.value=p.currency;rates.value={...woodRates(),...Object.fromEntries(Object.entries(p.sheetRates).map(([id,cents])=>[id,money(cents)])),handles:money(p.handleUnitCents),labour:money(p.labourHourlyCents)};
 minutes.value=p.labourMinutesPerPanel;markup.value=p.markupBps/100;includeEdging.value=!!p.edging;profilePrices.value=Object.fromEntries(Object.entries(p.profileRates??{}).map(([key,cents])=>[key,money(cents)]));
 edgeMaterial.value=money(p.edging?.materialCentsPerMetre??0);edgeLabour.value=money(p.edging?.labourCentsPerMetre??0);edgeWaste.value=(p.edging?.wasteBps??0)/100;
}
const preview=computed(()=>{try{validateQuoteDetails(details.value);return {cost:quoteCosting(props.revision.manifest,props.revision.number,pricing())};}catch(e){return {error:e.message};}});
const coverage=computed(()=>preview.value.cost?stockPricingCoverage(preview.value.cost.lines,preview.value.cost.pricing.stockRates??[]):null);
const coverageMessage=ref('');
function createCoverageOverrides(stocks){try{const values=addCoverageOverrides(validatePricing(pricing()).stockRates??[],stocks);stockRates.value=values.map(row=>({...row,price:(row.unitCents/100).toFixed(2)}));coverageMessage.value='Stock overrides created from effective prices';}catch(e){coverageMessage.value=e.message;}}
const saved=computed(()=>props.revision.quotes?.find(q=>q.id===choice.value));
watch(()=>props.revision.quotes,(quotes,previous)=>{if(quotes?.length&&(previous?.length!==quotes.length||!quotes.some(q=>q.id===choice.value)))choice.value=quotes.at(-1).id;},{deep:true,immediate:true});
watch(()=>props.focusId,id=>{if(props.revision.quotes?.some(q=>q.id===id))choice.value=id;},{immediate:true});
const amount=(cents,code=currency.value)=>(cents/100).toFixed(2)+' '+code;
</script>
<template>
  <section aria-label="Revision costing" class="job-quotes"><h4>Revision costing</h4>
    <p class="hint">User-entered planning rates. Material sheet rates are fallbacks; stock-specific overrides match material, thickness and ordered sheet dimensions. Whole stock sheets, handles, estimated panel labour, profile stock of placed designs (per metre, labour like panels) and optional edging are costed; tax, delivery, joinery and other services are excluded. Markup applies to the subtotal. Zero is allowed; no supplier prices are supplied.</p>
    <fieldset :disabled="busy"><PricingPresets :current="presetPricing" @apply="applyPricingPreset"/><CustomerRecords @choose="details={...details,...$event}"/><label>Quote recipient contact<textarea v-model="details.customerContact" maxlength="1000"></textarea></label><label>Quote customer<input v-model="details.customer" maxlength="120"></label><label>Quote reference<input v-model="details.reference" maxlength="80"></label><label>Quote notes<textarea v-model="details.notes" maxlength="1000"></textarea></label><label>Quote currency<select v-model="currency" aria-label="Quote currency"><option>EUR</option><option>USD</option><option>GBP</option></select></label>
      <label v-for="material in WOOD_IDS" :key="material">{{ material }} sheet price<input v-model="rates[material]" inputmode="decimal"></label>
      <label v-for="material in metals" :key="material">{{ material }} sheet price<input v-model="rates[material]" placeholder="0.00" inputmode="decimal"></label>
      <label v-for="profile in profileRows" :key="profile.key">{{ profile.label }} price per metre<input v-model="profilePrices[profile.key]" placeholder="0.00" inputmode="decimal"></label>
      <StockPriceOverrides :rows="stockRates" :batches="revision.manifest.batches" :fallback="rates" @update="stockRates=$event"/>
      <label>Handle unit price<input v-model="rates.handles" inputmode="decimal"></label><label>Labour hourly price<input v-model="rates.labour" inputmode="decimal"></label>
      <label>Labour minutes per panel<input v-model.number="minutes" type="number" min="0" max="600" step="1"></label><label>Quote markup percent<input v-model.number="markup" type="number" min="0" max="100" step="0.01"></label>
      <label class="snap-toggle"><input v-model="includeEdging" type="checkbox" aria-label="Include edging costs">Include edging costs</label><template v-if="includeEdging"><label>Edging material price per metre<input v-model="edgeMaterial" inputmode="decimal"></label><label>Edging labour price per metre<input v-model="edgeLabour" inputmode="decimal"></label><label>Edging material waste percent<input v-model.number="edgeWaste" type="number" min="0" max="100" step="0.01"></label><p class="hint">Net band length comes from the saved revision. Material waste increases purchased length; labour uses net length. Prices are additional to estimated panel labour. Lengths round once to mm; each cost rounds once to cents.</p></template>
      <PricingCoverage v-if="coverage" :coverage="coverage" @create="createCoverageOverrides"/><p v-if="coverageMessage" data-testid="pricing-coverage-message" role="status">{{ coverageMessage }}</p><p v-if="preview.error" role="status">{{ preview.error }}</p>
      <template v-if="preview.cost"><p v-if="preview.cost.edging" data-testid="edging-cost-preview">Edging net {{ (preview.cost.edging.netLengthMm/1000).toFixed(3) }} m · purchase {{ (preview.cost.edging.purchaseLengthMm/1000).toFixed(3) }} m · material {{ amount(preview.cost.edging.materialCents) }} · labour {{ amount(preview.cost.edging.labourCents) }}</p><p>Materials {{ amount(preview.cost.materialCents) }} · handles {{ preview.cost.handles }} · labour {{ preview.cost.labourMinutes }} minutes</p><p v-if="preview.cost.profiles" data-testid="profile-cost-preview">Profile stock {{ amount(preview.cost.profiles.totalCents) }} · {{ preview.cost.profiles.lines.reduce((n,l)=>n+l.pieces,0) }} pieces</p><ul v-if="preview.cost.pricing.stockRates" data-testid="stock-rate-breakdown"><li v-for="line in preview.cost.lines" :key="line.batch">Batch {{ line.batch }} · {{ line.material }} {{ line.thicknessMm.toFixed(3) }} mm · {{ line.stockLengthMm }} × {{ line.stockWidthMm }} mm · {{ line.rateSource==='stock'?'stock override':'material fallback' }} · {{ amount(line.unitCents) }} / sheet</li></ul><p data-testid="quote-preview">Subtotal {{ amount(preview.cost.subtotalCents) }} · markup {{ amount(preview.cost.markupCents) }} · total {{ amount(preview.cost.totalCents) }} (tax excluded)</p></template>
      <button :disabled="!preview.cost" @click="emit('save',{pricing:pricing(),details:validateQuoteDetails(details)})">Save revision quote snapshot</button>
      <label v-if="revision.quotes?.length">Saved quote<select v-model="choice" aria-label="Saved quote"><option v-for="(q,index) in revision.quotes" :key="q.id" :value="q.id">Quote {{ index+1 }} · {{ amount(q.costing.totalCents,q.costing.pricing.currency) }}</option></select></label>
      <template v-if="saved"><p v-if="saved.costing.edging" data-testid="saved-edging-cost">Saved edging {{ amount(saved.costing.edging.totalCents,saved.costing.pricing.currency) }} · net {{ (saved.costing.edging.netLengthMm/1000).toFixed(3) }} m</p><p data-testid="saved-quote">Saved total {{ amount(saved.costing.totalCents,saved.costing.pricing.currency) }} · revision {{ saved.costing.revision }} · {{ saved.createdAt }}</p><button @click="emit('export',JSON.stringify({format:'terratec-quote',version:1,...saved},null,2)+'\n')">Export saved quote JSON</button><button @click="emit('print',printableQuote(saved,jobName))">Export printable quote</button><p data-testid="quote-status">Quote status: {{ saved.lifecycle?.status || 'draft' }}</p><ol v-if="saved.lifecycle"><li v-for="event in saved.lifecycle.events" :key="event.number">{{ event.status }} · {{ event.actor }} · {{ event.at }} · {{ event.note }}</li></ol><template v-if="!saved.lifecycle||saved.lifecycle.status==='sent'"><label>Quote status actor<input v-model="statusActor" maxlength="80"></label><label>Quote status note<textarea v-model="statusNote" maxlength="1000"></textarea></label><button v-if="!saved.lifecycle" :disabled="!statusActor.trim()||!statusNote.trim()" @click="setStatus('sent')">Record quote as sent</button><template v-else><button v-for="state in ['accepted','declined','withdrawn']" :key="state" :disabled="!statusActor.trim()||!statusNote.trim()" @click="setStatus(state)">Record quote as {{ state }}</button></template></template><p class="hint">Status is a local record only. It sends no quote and does not capture authenticated customer acceptance.</p><p v-if="saved.details" data-testid="saved-quote-details">{{ saved.details.customer }} · {{ saved.details.reference }} · {{ saved.details.notes }}</p></template>
    </fieldset>
  </section>
</template>
